/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: draft, candidate, listing, decision, create, rows, appendTo
 *   Constants: lorem, ipsum, slotA, slotB, target, otherAlbum
 *   Variables: next
 * Tests
 *   - with no candidates every entry, the label, the Album and every track are preselected as create, and an explicit decision always wins
 *   - a case-insensitive name candidate blocks only its own row, and a candidate of another kind blocks nothing
 *   - an Album candidate blocks the Album and its tracks wait; an explicit create preselects them despite their candidates, and a skip preselects none
 *   - when appending, identical bytes on the target preselect reuse, a title-only member needs a choice, and a file with no member is a new one
 *   - ambiguous identical bytes preselect nothing: two files with one member's bytes, one file matching two members, or a member another file reuses
 *   - an append whose member matches are incomplete preselects no track, and the member cap is 300
 *   - an untitled file is never matched by title when appending, so an untitled member holds only the file its bytes match
 *   - the worker recheck reads no candidates for a format-1 or format-2 approval or one that froze no preselection, and refuses a malformed format-3 decision list
 *   - a same-name record too malformed to be a candidate keeps its row from being preselected, and only that row
 *   - names compare without the host locale, so a Turkish default locale still matches a dotted capital I
 *   - an approval matches only the exact preselections its confirmation showed, candidate revisions included, and refuses malformed ones
 *   - the candidate projection and revision moved without change and are still the ones the service exports
 * @end-catalog */

/**
 * The name-based identity preselection matrix without a database (adminImportIdentity.ts): which rows the review preselects as
 * create or reuse, which need an explicit choice, how explicit decisions and appends change that, which approvals the worker
 * recheck skips, and that the moved candidate revision is the one the service still exports. All names, identifiers and slots are
 * synthetic.
 */
import assert from 'node:assert/strict';
import { mock, test } from 'node:test';
// The database module loads first; importing adminImportService before it trips the index import cycle.
import '../../src/infrastructure/database';
import type { ImportCandidatesResponse, ImportDuplicateCandidate } from '../../src/administration/import/adminImportContract';
import type { ClientSession } from 'mongodb';
import type { ImportDecisionV2, ImportDraftV2 } from '../../src/administration/import/adminImportDraft';
import type { ImportPublication } from '../../src/administration/import/adminImportMediaTypes';
import { AdminImportError } from '../../src/administration/import/adminImportContract';
import { IMPORT_MEMBER_MATCH_LIMIT, assertImportPreselectionsCurrent, importCandidateProjection as movedProjection, importCandidateRevision as movedRevision, importIdentityPreselections, sameImportPreselections, shownPreselectionKey } from '../../src/administration/import/adminImportIdentity';
import { importCandidateProjection, importCandidateRevision } from '../../src/administration/import/adminImportService';

const lorem = '00000009-0000-4000-a000-0000000000a1', ipsum = '00000009-0000-4000-a000-0000000000a2';
const slotA = '00000009-0000-4000-a000-0000000000c1', slotB = '00000009-0000-4000-a000-0000000000c2';
const target = '0000000000000000000000d1', otherAlbum = '0000000000000000000000d2';
const draft = (change: (value: ImportDraftV2) => void = () => undefined): ImportDraftV2 => {
    const value: ImportDraftV2 = {
        album: { title: 'Amet Collection', artists: [{ key: lorem, name: 'Lorem Ensemble', role: 'primary', joinPhrase: ' & ', musicBrainzId: null }, { key: ipsum, name: 'Ipsum Quartet', role: 'featured', joinPhrase: null, musicBrainzId: null }],
            label: { name: 'Sit Records', musicBrainzId: null }, releaseDate: null, visibility: 'public' },
        tracks: [{ slotId: slotA, title: 'Consectetur', discNumber: null, trackNumber: 1 }, { slotId: slotB, title: 'Adipiscing', discNumber: null, trackNumber: 2 }]
    };
    change(value); return value;
};
let next = 0;
const candidate = (kind: ImportDuplicateCandidate['kind'], label: string, extra: Partial<ImportDuplicateCandidate> = {}): ImportDuplicateCandidate =>
    ({ kind, id: (++next).toString(16).padStart(24, '0'), label, revision: 'f'.repeat(64), albumId: null, visibility: 'public', match: 'name', matchedSlotIds: [], automaticReuse: false, ...extra });
const listing = (items: ImportDuplicateCandidate[], memberMatchesComplete = true, unavailable: ImportCandidatesResponse['unavailable'] = []): ImportCandidatesResponse => ({ items, memberMatchesComplete, unavailable });
const decision = (scope: ImportDecisionV2['scope'], action: ImportDecisionV2['action'], extra: Partial<ImportDecisionV2> = {}): ImportDecisionV2 =>
    ({ scope, slotId: null, entryKey: null, boundName: null, action, candidateId: null, candidateRevision: null, ...extra });
const create = (scope: ImportDecisionV2['scope'], extra: Partial<ImportDecisionV2> = {}) => ({ ...decision(scope, 'create-distinct', extra), preselected: true });
/** The rows a preselection covers, as `scope:slot-or-entry:action[:candidate]`. */
const rows = (decisions: readonly ImportDecisionV2[]) => decisions.map(value => [value.scope, value.slotId ?? value.entryKey ?? '-', value.action, ...(value.candidateId ? [value.candidateId] : [])].join(':'));
const appendTo = (albumId: string, extra: ImportDecisionV2[] = []) => [decision('album', 'reuse', { candidateId: albumId, candidateRevision: 'e'.repeat(64) }), ...extra];

test('with no candidates every entry, the label, the Album and every track are preselected as create, and an explicit decision always wins', () => {
    const value = draft();
    assert.deepEqual(importIdentityPreselections(value, [], listing([])), [
        create('artist', { entryKey: lorem, boundName: 'Lorem Ensemble' }), create('artist', { entryKey: ipsum, boundName: 'Ipsum Quartet' }), create('label', { boundName: 'Sit Records' }),
        create('album'), create('track', { slotId: slotA }), create('track', { slotId: slotB })]);
    // Explicit decisions, a skip included, are never preselected over; the other rows still are.
    const explicit = [decision('artist', 'skip', { entryKey: lorem, boundName: 'Lorem Ensemble' }), decision('label', 'create-distinct', { boundName: 'Sit Records' }), decision('track', 'skip', { slotId: slotA })];
    assert.deepEqual(rows(importIdentityPreselections(value, explicit, listing([]))), [`artist:${ipsum}:create-distinct`, 'album:-:create-distinct', `track:${slotB}:create-distinct`]);
    // A decision made for an earlier name binds nothing, so the renamed entry and label are preselected again.
    const stale = [decision('artist', 'create-distinct', { entryKey: lorem, boundName: 'Lorem Earlier' }), decision('label', 'create-distinct', { boundName: 'Sit Earlier' })];
    assert.deepEqual(rows(importIdentityPreselections(value, stale, listing([]))).slice(0, 3), [`artist:${lorem}:create-distinct`, `artist:${ipsum}:create-distinct`, 'label:-:create-distinct']);
    // An empty label preselects nothing for it.
    assert.equal(importIdentityPreselections(draft(item => { item.album.label = null; }), [], listing([])).some(item => item.scope === 'label'), false);
});

test('a case-insensitive name candidate blocks only its own row, and a candidate of another kind blocks nothing', () => {
    const value = draft();
    assert.deepEqual(rows(importIdentityPreselections(value, [], listing([candidate('artist', 'LOREM ensemble')]))),
        [`artist:${ipsum}:create-distinct`, 'label:-:create-distinct', 'album:-:create-distinct', `track:${slotA}:create-distinct`, `track:${slotB}:create-distinct`]);
    // An Artist named like the label, or an Organization named like an entry, is not a candidate of that row's kind.
    assert.equal(importIdentityPreselections(value, [], listing([candidate('artist', 'sit records'), candidate('organization', 'Ipsum Quartet')])).length, 6);
    assert.deepEqual(rows(importIdentityPreselections(value, [], listing([candidate('organization', 'SIT RECORDS')]))).filter(row => row.startsWith('label')), []);
});

test('an Album candidate blocks the Album and its tracks wait; an explicit create preselects them despite their candidates, and a skip preselects none', () => {
    const value = draft(), album = candidate('album', 'amet collection');
    const trackMatches = [candidate('track', 'Consectetur', { albumId: otherAlbum, matchedSlotIds: [slotA] }), candidate('track', 'Synthetic Other', { albumId: otherAlbum, match: 'sha256', matchedSlotIds: [slotB] })];
    assert.deepEqual(rows(importIdentityPreselections(value, [], listing([album, ...trackMatches]))), [`artist:${lorem}:create-distinct`, `artist:${ipsum}:create-distinct`, 'label:-:create-distinct']);
    assert.deepEqual(rows(importIdentityPreselections(value, [decision('album', 'create-distinct')], listing([album, ...trackMatches]))).slice(3), [`track:${slotA}:create-distinct`, `track:${slotB}:create-distinct`]);
    assert.deepEqual(rows(importIdentityPreselections(value, [decision('album', 'skip')], listing([]))), [`artist:${lorem}:create-distinct`, `artist:${ipsum}:create-distinct`, 'label:-:create-distinct']);
    // Track name candidates alone never hold a new Album's tracks.
    assert.equal(importIdentityPreselections(value, [], listing(trackMatches)).filter(item => item.scope === 'track').length, 2);
});

test('when appending, identical bytes on the target preselect reuse, a title-only member needs a choice, and a file with no member is a new one', () => {
    const value = draft(), member = candidate('track', 'Different Title', { albumId: target, match: 'sha256', matchedSlotIds: [slotA], revision: 'a'.repeat(64) });
    const reused = importIdentityPreselections(value, appendTo(target), listing([member]));
    assert.deepEqual(reused, [{ scope: 'track', slotId: slotA, entryKey: null, boundName: null, action: 'reuse', candidateId: member.id, candidateRevision: 'a'.repeat(64), preselected: true }, create('track', { slotId: slotB })]);
    // Entries and the label are not applied in an append: nothing is preselected for them.
    assert.equal(reused.some(item => item.scope === 'artist' || item.scope === 'label' || item.scope === 'album'), false);
    // A member titled like the file needs an explicit choice, also when its bytes match another file.
    const titled = candidate('track', 'adipiscing', { albumId: target }), crossed = candidate('track', 'ADIPISCING', { albumId: target, match: 'sha256', matchedSlotIds: [slotA] });
    assert.deepEqual(rows(importIdentityPreselections(value, appendTo(target), listing([titled]))), [`track:${slotA}:create-distinct`]);
    assert.deepEqual(rows(importIdentityPreselections(value, appendTo(target), listing([crossed]))), [`track:${slotA}:reuse:${crossed.id}`]);
    // Identical bytes on another Album are only a flag: the file is still a new member of the target.
    assert.deepEqual(rows(importIdentityPreselections(value, appendTo(target), listing([candidate('track', 'Consectetur', { albumId: otherAlbum, match: 'sha256', matchedSlotIds: [slotA] })]))),
        [`track:${slotA}:create-distinct`, `track:${slotB}:create-distinct`]);
    // An explicit track decision wins over its preselection.
    assert.deepEqual(rows(importIdentityPreselections(value, appendTo(target, [decision('track', 'skip', { slotId: slotA })]), listing([member]))), [`track:${slotB}:create-distinct`]);
});

test('ambiguous identical bytes preselect nothing: two files with one member\'s bytes, one file matching two members, or a member another file reuses', () => {
    const value = draft();
    const shared = candidate('track', 'Shared', { albumId: target, match: 'sha256', matchedSlotIds: [slotA, slotB] });
    assert.deepEqual(importIdentityPreselections(value, appendTo(target), listing([shared])), []);
    const first = candidate('track', 'First', { albumId: target, match: 'sha256', matchedSlotIds: [slotA] }), second = candidate('track', 'Second', { albumId: target, match: 'sha256', matchedSlotIds: [slotA] });
    assert.deepEqual(rows(importIdentityPreselections(value, appendTo(target), listing([first, second]))), [`track:${slotB}:create-distinct`]);
    const explicit = decision('track', 'reuse', { slotId: slotB, candidateId: first.id, candidateRevision: first.revision });
    assert.deepEqual(importIdentityPreselections(value, appendTo(target, [explicit]), listing([first])), []);
});

test('an append whose member matches are incomplete preselects no track, and the member cap is 300', () => {
    assert.equal(IMPORT_MEMBER_MATCH_LIMIT, 300);
    assert.deepEqual(importIdentityPreselections(draft(), appendTo(target), listing([], false)), []);
    // A new Album does not depend on member matches.
    assert.equal(importIdentityPreselections(draft(), [], listing([], false)).length, 6);
});

test('an untitled file is never matched by title when appending, so an untitled member holds only the file its bytes match', () => {
    const value = draft(item => { item.tracks[0].title = ''; }), untitled = candidate('track', '', { albumId: target, match: 'sha256', matchedSlotIds: [slotB] });
    assert.deepEqual(rows(importIdentityPreselections(value, appendTo(target), listing([untitled]))), [`track:${slotA}:create-distinct`, `track:${slotB}:reuse:${untitled.id}`]);
});

test('the worker recheck reads no candidates for a format-1 or format-2 approval or one that froze no preselection, and refuses a malformed format-3 decision list', async () => {
    const snapshot = draft(value => { value.album.artists = [value.album.artists[0]]; value.album.label = null; }), format3 = { schemaVersion: 3, snapshot, artists: [{}], label: null };
    const source = { manifest: { rootLabel: 'Synthetic', files: [] }, assets: [] }, session = {} as ClientSession;
    const recheck = (publication: Record<string, unknown>) => assertImportPreselectionsCurrent(publication as unknown as ImportPublication, source, session);
    // This unit test never connects a database, so a candidate read would reject: each of these returns before one.
    for (const publication of [
        { snapshot: { album: { artistName: 'Lorem Ensemble', title: 'Amet Collection' }, tracks: [{ slotId: slotA, title: 'Consectetur' }] }, decisions: [create('album')] },
        { ...format3, schemaVersion: 2, artists: undefined, decisions: [create('album')] },
        { ...format3, decisions: [decision('album', 'create-distinct'), decision('track', 'create-distinct', { slotId: slotA })] }
    ]) await recheck(publication);
    // A format-3 list in another shape cannot prove its preselections: a catalog conflict, still without a candidate read.
    for (const decisions of ['malformed', null, [null, 7, decision('album', 'create-distinct')], [create('album'), 'preselected']])
        await assert.rejects(recheck({ ...format3, decisions }), (error: unknown) => error instanceof AdminImportError && error.code === 'ADMIN_IMPORT_PUBLICATION_CONFLICT', JSON.stringify(decisions));
    // The same format-3 approval with one frozen preselection does read candidates.
    await assert.rejects(recheck({ ...format3, decisions: [create('album')] }), TypeError);
});

test('a same-name record too malformed to be a candidate keeps its row from being preselected, and only that row', () => {
    const value = draft(), unavailable: ImportCandidatesResponse['unavailable'] = [{ kind: 'artist', label: 'lorem ensemble' }, { kind: 'organization', label: 'SIT RECORDS' }];
    assert.deepEqual(rows(importIdentityPreselections(value, [], listing([], true, unavailable))), [`artist:${ipsum}:create-distinct`, 'album:-:create-distinct', `track:${slotA}:create-distinct`, `track:${slotB}:create-distinct`]);
    // A malformed Album titled like the draft holds the Album, and so its tracks, for an explicit choice.
    assert.deepEqual(rows(importIdentityPreselections(value, [], listing([], true, [{ kind: 'album', label: 'Amet Collection' }]))), [`artist:${lorem}:create-distinct`, `artist:${ipsum}:create-distinct`, 'label:-:create-distinct']);
    // A name of another kind holds nothing.
    assert.equal(importIdentityPreselections(value, [], listing([], true, [{ kind: 'album', label: 'Lorem Ensemble' }])).length, 6);
});

test('names compare without the host locale, so a Turkish default locale still matches a dotted capital I', () => {
    const lower = String.prototype.toLocaleLowerCase;
    // Under a Turkish default locale, 'I' lowers to a dotless i: a locale-dependent comparison would miss this candidate.
    const turkish = mock.method(String.prototype, 'toLocaleLowerCase', function (this: string) { return lower.call(this, 'tr'); });
    try {
        assert.notEqual('IPSUM QUARTET'.toLocaleLowerCase(), 'ipsum quartet'.toLocaleLowerCase());
        const lowered = draft(value => { value.album.artists[1].name = 'ipsum quartet'; });
        assert.deepEqual(rows(importIdentityPreselections(lowered, [], listing([candidate('artist', 'IPSUM QUARTET')]))).filter(row => row.startsWith('artist')), [`artist:${lorem}:create-distinct`]);
        assert.equal(importIdentityPreselections(draft(), [], listing([], true, [{ kind: 'organization', label: 'SIT RECORDS' }])).some(item => item.scope === 'label'), false);
    } finally { turkish.mock.restore(); }
});

test('an approval matches only the exact preselections its confirmation showed, candidate revisions included, and refuses malformed ones', () => {
    const member = candidate('track', 'Different Title', { albumId: target, match: 'sha256', matchedSlotIds: [slotA], revision: 'a'.repeat(64) });
    const computed = importIdentityPreselections(draft(), appendTo(target), listing([member]));
    const shown = computed.map(({ preselected: _, ...value }) => value);
    assert.equal(sameImportPreselections(shown, computed), true);
    assert.equal(sameImportPreselections([...shown].reverse(), computed), true);
    assert.equal(sameImportPreselections([], []), true);
    for (const [what, value] of [
        ['a file shown as a new member now reuses one', [shown[1], { ...shown[0], action: 'create-distinct', candidateId: null, candidateRevision: null }]],
        ['a reuse shown at an earlier revision', [{ ...shown[0], candidateRevision: 'b'.repeat(64) }, shown[1]]],
        ['one missing', [shown[0]]], ['one extra', [...shown, { ...shown[1], slotId: lorem }]], ['a duplicate', [shown[0], shown[0], shown[1]]]
    ] as const) assert.equal(sameImportPreselections(value as readonly unknown[], computed), false, what);
    for (const value of [null, [], 'reuse', { ...shown[0], preselected: true }, { ...shown[0], scope: 'skip' }, { ...shown[0], action: 'skip' }, { ...shown[0], slotId: 7 }, { ...shown[0], boundName: 'x'.repeat(301) }, { ...shown[0], candidateId: undefined }])
        assert.equal(shownPreselectionKey(value), null, JSON.stringify(value));
    assert.equal(sameImportPreselections([...shown, null], [...computed]), false);
});

test('the candidate projection and revision moved without change and are still the ones the service exports', () => {
    assert.equal(importCandidateRevision, movedRevision);
    assert.equal(importCandidateProjection, movedProjection);
});
